import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.D4fUSYzX.js";const w=JSON.parse('{"title":"ADR 0086: The settling agent writes the operator-owned labels","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0086-the-settling-agent-writes-the-operator-owned-labels.md","filePath":"adr/0086-the-settling-agent-writes-the-operator-owned-labels.md"}'),i={name:"adr/0086-the-settling-agent-writes-the-operator-owned-labels.md"};function s(r,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0086-the-settling-agent-writes-the-operator-owned-labels" tabindex="-1">ADR 0086: The settling agent writes the operator-owned labels <a class="header-anchor" href="#adr-0086-the-settling-agent-writes-the-operator-owned-labels" aria-label="Permalink to &quot;ADR 0086: The settling agent writes the operator-owned labels&quot;">​</a></h1><p>Status: accepted Date: 2026-10-02</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The standing rule is that the agents never write workflow labels: the plane&#39;s fire is the only writer of the machine-owned label facts a Transition names, and the operator-owned entry labels - for example <code>ready-for-agent</code> - are the operator&#39;s to write. The <code>analyze</code> task type&#39;s interview ends with the design settled, and the ticket needs to move to the implementation position. The agent already runs gh in the session - it reads the ticket and writes the specification - and waiting for the operator to label the ticket by hand after every interview is friction in a flow the operator has put in the machine&#39;s hands.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>A sanctioned exception, named in the <code>analyze</code> template: when, and only when, the specification is settled and the documentation is committed, the agent applies <code>ready-for-agent</code> to the ticket through gh. In the fallback, where the ticket body cannot be edited and the specification opens in a second issue, the agent additionally applies a <code>spec:&lt;issue number&gt;</code> label carrying that issue&#39;s number.</p><p>The agent writes only operator-owned labels the template names: a label no Transition writes. It never writes a label the machine writes in a Transition, and it never writes a label the template does not name. The rule&#39;s wording updates where it stands: the agents never write the labels the machine writes.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The ticket moves to the implementation position at session end without operator action, and the machine picks the label up on its source refresh, because the position is re-derived on every refresh and never stored.</li><li>The operator keeps the gate: in auto mode the implementation starts only after their close of the parked cycle (ADR 0085), and a specification they reject is rewound through the Placement, an override back to <code>analyze</code> re-places the labels onto the spec state.</li><li>A write the operator did not want is visible as a plain external label write and removable the same way any label is; the exception is bounded to the template&#39;s named labels, so the machine-owned set stays machine-only.</li></ul>',9)])])}const m=t(i,[["render",s]]);export{w as __pageData,m as default};
